// Copies the contract types from the repo root into src/contract/ so the web has no cross-folder imports.
// Source of truth: ../../contract/types.ts  — do NOT edit src/contract/types.ts by hand.
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = resolve(here, "../../../contract/types.ts");
const dst = resolve(here, "../src/contract/types.ts");

if (!existsSync(src)) {
  console.log("[contract:sync] source not found (standalone web?). Keeping existing src/contract/types.ts");
  process.exit(0);
}
mkdirSync(dirname(dst), { recursive: true });
copyFileSync(src, dst);
const header = "// AUTO-GENERATED by scripts/sync-contract.mjs from /contract/types.ts — DO NOT EDIT BY HAND.\n";
writeFileSync(dst, header + readFileSync(dst, "utf8"));
console.log("[contract:sync] src/contract/types.ts updated");
